/**
 * Geometry of the dotted Africa (public/images/africa-dots.svg, generated by
 * scripts/africa-dots.mjs from Natural Earth 1:110m, public domain). The map
 * is a plate carree projection: x = lon + 19, y = 39 - lat on a 72 x 76 box,
 * so a pin can be placed over the <img> with plain percentages.
 */

export const AFRICA_VIEW = { width: 72, height: 76 } as const;
export const AFRICA_VIEW_BOX = `0 0 ${AFRICA_VIEW.width} ${AFRICA_VIEW.height}`;
export const AFRICA_SRC = "/images/africa-dots.svg";

export type MapRegion = {
  /** Centre of the region. */
  lat: number;
  lon: number;
  /** Radius in degrees: the ring drawn around the centre marks the region. */
  radius: number;
};

/**
 * Southwest Nigeria, the six-state geopolitical zone, as a region: its
 * approximate centre and a radius that covers it. The site marks the region
 * only; no town or state is named (the client's instruction, 3 October 2026).
 */
export const SOUTHWEST_NIGERIA: MapRegion = { lat: 7.6, lon: 4.3, radius: 2.2 };

/** Latitude and longitude to map units (the SVG's user space). */
export function project(lat: number, lon: number): { x: number; y: number } {
  return { x: lon + 19, y: 39 - lat };
}

/**
 * Latitude and longitude to percentages of the map box, for an HTML pin
 * positioned absolutely over the image (`left`, `top`).
 */
export function projectPercent(
  lat: number,
  lon: number,
): { left: string; top: string } {
  const { x, y } = project(lat, lon);
  const pct = (v: number) => `${Math.round(v * 1000) / 1000}%`;
  return {
    left: pct((x / AFRICA_VIEW.width) * 100),
    top: pct((y / AFRICA_VIEW.height) * 100),
  };
}

/**
 * A region's ring as a percentage of the map's width (its diameter), so the
 * ring scales with the map. One degree is one map unit on this projection.
 */
export function regionWidthPercent(radius: number): string {
  const pct = ((2 * radius) / AFRICA_VIEW.width) * 100;
  return `${Math.round(pct * 1000) / 1000}%`;
}
